import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { defineConfig } from "vite-plus";

/**
 * Assets are generated by `scripts/build-sea.ts` after the web app and the
 * extracted libSQL runtime are built. Keeping the manifest outside this file
 * avoids a hard dependency on build order when running a plain `vp pack`.
 */
const assetManifest = fileURLToPath(new URL("./.sea-assets.json", import.meta.url));
const assets: Record<string, string> = existsSync(assetManifest)
	? (JSON.parse(readFileSync(assetManifest, "utf8")) as Record<string, string>)
	: {};
const hasAssets = Object.keys(assets).length > 0;

export default defineConfig({
	pack: {
		entry: ["main.ts"],
		format: ["esm"],
		platform: "node",
		dts: false,
		sourcemap: false,
		clean: true,
		deps: {
			// Bundle the CLI, server, TUI, and their JS dependencies. The libSQL
			// native client is loaded from the extracted runtime via createRequire.
			alwaysBundle: () => true,
			onlyBundle: false,
		},
		inputOptions: {
			transform: {
				// The CLI's JSX runtime lives behind its `#/` package import. The
				// local entry needs to set it explicitly because it uses its own
				// tsconfig, not packages/cli/tsconfig.json.
				jsx: { runtime: "automatic", importSource: "#/tui/render" },
			},
		},
		// Only build a SEA when `scripts/build-sea.ts` has prepared the asset
		// manifest. A plain `vp pack` still produces the JS bundle.
		exe: hasAssets
			? {
					fileName: "relay",
					outDir: "../../dist",
					seaConfig: {
						assets,
						useCodeCache: false,
					},
				}
			: false,
	},
});
